    private val stationMap: Map<String, Station> = allIndiaStations.associateBy { it.code.uppercase() }

    fun findByCode(code: String): Station? = stationMap[code.uppercase().trim()]

    fun getStationByCode(code: String): Station? = findByCode(code)

    fun getOrSynthesize(codeOrName: String): Station {
        val query = codeOrName.trim().uppercase()
        val found = stationMap[query]
        if (found != null) return found

        // Search by partial English name match
        val nameMatch = allIndiaStations.find {
            it.nameEn.equals(codeOrName.trim(), ignoreCase = true) ||
            it.nameBn.equals(codeOrName.trim(), ignoreCase = true) ||
            it.nameHi.equals(codeOrName.trim(), ignoreCase = true)
        }
        if (nameMatch != null) return nameMatch

        // Synthesize dynamic station so any IRCTC station code in India works seamlessly!
        val cleanCode = if (query.length in 2..5 && query.all { it.isLetter() }) query else query.take(4)
        return Station(
            code = cleanCode,
            nameEn = "$codeOrName Junction",
            nameBn = "$codeOrName জংশন",
            nameHi = "$codeOrName जंक्शन",
            cityEn = codeOrName,
            cityBn = codeOrName,
            cityHi = codeOrName,
            state = "India (IRCTC)"
        )
    }
